public class Tierheim {

    public static void main(String[] args) {
        Haustier[] heim = {new Hund("Bello"), new Katze("Mimi")};
        for (Haustier tier : heim) {
            System.out.println(tier.lauten());
        }
    }
}

abstract class Haustier {
    String name;

    Haustier(String name) {
        this.name = name;
    }

    abstract String lauten();
}

class Hund extends Haustier {

    Hund(String name) {
        super(name);
    }

    String lauten() {
        return name + " sagt: Wuff";
    }
}

class Katze extends Haustier {

    Katze(String name) {
        super(name);
    }

    String lauten() {
        return name + " sagt: Miau";
    }
}
